"""PAL-style quiz questions for MAF Metall/Kunststoff curriculum."""

from __future__ import annotations

from app.data.content.helpers import quiz
from app.data.content.subchapters import MONTH_SUBCHAPTERS, slugify
from app.data.machine_operator import MACHINE_OPERATOR_CURRICULUM
from app.models.domain import QuizQuestion

_SOURCE_KEYS_BY_MONTH: dict[int, list[str]] = {
    entry.month: list(entry.source_keys) for entry in MACHINE_OPERATOR_CURRICULUM
}


def _category_slug(month: int, sub: int) -> str:
    title = MONTH_SUBCHAPTERS[month][sub - 1]
    return f"m{month:02d}-{slugify(title)}"


def _q(
    month: int,
    sub: int,
    n: int,
    *,
    prompt: str,
    correct: str,
    distractors: list[str],
    explanation: str,
    exam_style: str = "single_choice",
) -> QuizQuestion:
    return quiz(
        question_id=f"q-{month:02d}-{sub:02d}-{n}",
        category_slug=_category_slug(month, sub),
        prompt=prompt,
        correct=correct,
        distractors=distractors,
        explanation=explanation,
        source_keys=_SOURCE_KEYS_BY_MONTH[month],
        exam_style=exam_style,
    )


